<script>
(function(){
'use strict';

var c=document.getElementById('canvas'),x=c.getContext('2d'),W,H,D=1,N=25,speed=5,mode='play',cells=[],stack=[],player={i:0,j:0},goal={i:0,j:0},steps=0,path=[],solution=[],solveTick=0;
var hs=document.getElementById('h-size'),ht=document.getElementById('h-steps'),hp=document.getElementById('h-path'),hm=document.getElementById('h-mode'),ss=document.getElementById('sl-size'),sp=document.getElementById('sl-speed'),vs=document.getElementById('sv-size'),vp=document.getElementById('sv-speed');
function resize(){D=Math.min(2,devicePixelRatio||1);W=c.width=Math.floor(innerWidth*D);H=c.height=Math.floor(innerHeight*D);c.style.width=innerWidth+'px';c.style.height=innerHeight+'px'}function cell(i,j){return cells[j*N+i]}function idx(i,j){return j*N+i}function rnd(n){return Math.sin(n*91.7+N*13.1)*.5+.5}
function gen(){cells=[];for(var j=0;j<N;j++)for(var i=0;i<N;i++)cells.push({i:i,j:j,w:[1,1,1,1],v:0});var cur=cell(0,0),st=[cur];cur.v=1;var seed=1;while(st.length){cur=st[st.length-1];var ns=[];[[0,-1,0,2],[1,0,1,3],[0,1,2,0],[-1,0,3,1]].forEach(function(d){var ni=cur.i+d[0],nj=cur.j+d[1];if(ni>=0&&nj>=0&&ni<N&&nj<N&&!cell(ni,nj).v)ns.push([cell(ni,nj),d[2],d[3]])});if(ns.length){var pick=ns[Math.floor(rnd(seed++)*ns.length)];cur.w[pick[1]]=0;pick[0].w[pick[2]]=0;pick[0].v=1;st.push(pick[0])}else st.pop()}player={i:0,j:0};goal={i:N-1,j:N-1};steps=0;path=[[0,0]];solution=findPath();solveTick=0;hud()}
function findPath(){var q=[[0,0]],prev={};prev['0,0']='';while(q.length){var p=q.shift(),ce=cell(p[0],p[1]);if(p[0]===goal.i&&p[1]===goal.j)break;[[0,-1,0],[1,0,1],[0,1,2],[-1,0,3]].forEach(function(d){var ni=p[0]+d[0],nj=p[1]+d[1],k=ni+','+nj;if(ni>=0&&nj>=0&&ni<N&&nj<N&&!ce.w[d[2]]&&!(k in prev)){prev[k]=p[0]+','+p[1];q.push([ni,nj])}})}var out=[],k=goal.i+','+goal.j;while(k){var parts=k.split(',');out.push([+parts[0],+parts[1]]);k=prev[k]}return out.reverse()}
function move(di,dj){var ce=cell(player.i,player.j),dir=di===1?1:di===-1?3:dj===1?2:0;if(ce.w[dir])return;player.i+=di;player.j+=dj;steps++;path.push([player.i,player.j]);if(window.SFX)SFX.play(player.i===goal.i&&player.j===goal.j?'success':'tick',100);hud()}
function draw(){x.fillStyle='rgba(10,10,15,.22)';x.fillRect(0,0,W,H);if(mode==='solve'&&solveTick<solution.length){var p=solution[Math.floor(solveTick)];player={i:p[0],j:p[1]};solveTick+=speed*.03}var s=Math.min(W,H)*.78/N,ox=(W-s*N)/2,oy=(H-s*N)/2;x.lineWidth=Math.max(1,D);x.strokeStyle='rgba(0,245,212,.22)';for(var j=0;j<N;j++)for(var i=0;i<N;i++){var ce=cell(i,j),px=ox+i*s,py=oy+j*s;x.beginPath();if(ce.w[0]){x.moveTo(px,py);x.lineTo(px+s,py)}if(ce.w[1]){x.moveTo(px+s,py);x.lineTo(px+s,py+s)}if(ce.w[2]){x.moveTo(px+s,py+s);x.lineTo(px,py+s)}if(ce.w[3]){x.moveTo(px,py+s);x.lineTo(px,py)}x.stroke()}x.globalCompositeOperation='lighter';x.strokeStyle='rgba(123,44,191,.45)';x.beginPath();path.forEach(function(p,k){var px=ox+(p[0]+.5)*s,py=oy+(p[1]+.5)*s;if(k)x.lineTo(px,py);else x.moveTo(px,py)});x.stroke();x.fillStyle='rgba(123,44,191,.75)';x.fillRect(ox+goal.i*s+s*.25,oy+goal.j*s+s*.25,s*.5,s*.5);x.fillStyle='rgba(0,245,212,.95)';x.beginPath();x.arc(ox+(player.i+.5)*s,oy+(player.j+.5)*s,s*.28,0,Math.PI*2);x.fill();x.globalCompositeOperation='source-over';requestAnimationFrame(draw)}
function hud(){hs.textContent=N;ht.textContent=steps;hp.textContent=solution.length;hm.textContent=mode.toUpperCase();vs.textContent=N;vp.textContent=speed}c.addEventListener('pointerdown',function(e){var s=Math.min(W,H)*.78/N,ox=(W-s*N)/2,oy=(H-s*N)/2,mi=Math.floor((e.clientX*D-ox)/s),mj=Math.floor((e.clientY*D-oy)/s);var di=Math.sign(mi-player.i),dj=Math.sign(mj-player.j);if(Math.abs(mi-player.i)>Math.abs(mj-player.j))move(di,0);else move(0,dj)});addEventListener('keydown',function(e){if(e.key==='ArrowUp')move(0,-1);if(e.key==='ArrowDown')move(0,1);if(e.key==='ArrowLeft')move(-1,0);if(e.key==='ArrowRight')move(1,0)});document.querySelectorAll('[data-mode]').forEach(function(b){b.onclick=function(){mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(function(q){q.classList.toggle('active',q===b)});solveTick=0;hud();if(window.SFX)SFX.play('toggle')}});ss.oninput=function(){N=+ss.value;gen();hud()};sp.oninput=function(){speed=+sp.value;hud()};document.getElementById('btn-new').onclick=function(){gen();if(window.SFX)SFX.play('success')};document.getElementById('btn-reset').onclick=function(){player={i:0,j:0};path=[[0,0]];steps=0;solveTick=0;hud();if(window.SFX)SFX.play('toggle')};addEventListener('resize',resize);resize();gen();draw();
})();
</script>
